export function Prefetching({
  trigger = "{{trigger}}",
  prefetched = {{prefetched}},
  linkLabel = "{{linkLabel}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 18, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <a href="#" style={{ display: "inline-flex", alignItems: "center", gap: 8, color: "#241430", fontWeight: 600, textDecoration: "none", borderBottom: "1.5px solid #241430", paddingBottom: 2 }}>
        {linkLabel} {prefetched && <span style={{ fontSize: 10, fontWeight: 700, textTransform: "uppercase", color: "#241430", padding: "2px 6px", borderRadius: 999, background: accent }}>prefetched</span>}
      </a>
      <p style={{ margin: "12px 0 0" }}>On {trigger}, the next page's data loads quietly in the background &mdash; so the click feels instant</p>
    </div>
  );
}
